 "content": "def transform(grid):
    """Recolor the regular full-width/full-height separator lines to 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        if len(set(row)) == 1:
            c = row[0]
            counts[c] = counts.get(c, 0) + 1
    for j in range(w):
        c = grid[0][j]
        if all(grid[i][j] == c for i in range(h)):
            counts[c] = counts.get(c, 0) + 1
    # The separator color is the one forming full uniform rows/columns.
    # Preserve anomalous occurrences of it away from those lines.
    if not counts:
        return [row[:] for row in grid]
    color = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for i in range(h):
        if all(grid[i][j] == color for j in range(w)):
            for j in range(w):
                out[i][j] = 2
    for j in range(w):
        if all(grid[i][j] == color for i in range(h)):
            for i in range(h):
                out[i][j] = 2
    return out
